84	    /// Set the `OpenAI-Project` header.
85	    pub fn project(mut self, project: impl Into<String>) -> Self {
86	        self.project = Some(project.into());
87	        self
88	    }
89	
90	    /// Use a caller-provided `reqwest::Client`.
91	    pub fn http_client(mut self, client: reqwest::Client) -> Self {
92	        self.http_client = Some(client);
93	        self
94	    }
95	
96	    /// Override the capability snapshot. Wins over the built-in model lookup table.
97	    pub fn with_capabilities(mut self, caps: ModelCapabilities) -> Self {
98	        self.capabilities_override = Some(caps);
99	        self
100	    }
