102	    /// Resolve auth, validate base URL, look up capabilities, produce [`OpenAiModel`].
103	    pub fn build(self) -> Result<OpenAiModel, BuildError> {
104	        let api_key = match &self.auth {
105	            AuthSource::Env => {
106	                std::env::var("OPENAI_API_KEY").map_err(|_| BuildError::MissingApiKey)?
107	            }
108	            AuthSource::ApiKey(k) => k.clone(),
109	            AuthSource::Bearer(t) => t.clone(),
110	        };
111	
112	        let mut config = OpenAIConfig::new().with_api_key(api_key);
113	        if let Some(url) = &self.base_url {
114	            if reqwest::Url::parse(url).is_err() {
115	                return Err(BuildError::InvalidBaseUrl(url.clone()));
116	            }
117	            config = config.with_api_base(url);
118	        }
119	        if let Some(org) = &self.organization {
120	            config = config.with_org_id(org);
121	        }
122	        if let Some(project) = &self.project {
123	            config = config.with_project_id(project);
124	        }
125	
126	        let caps = self.capabilities_override.unwrap_or_else(|| {
127	            capabilities::mask_for_backend(capabilities::lookup(&self.model_id), self.backend)
128	        });
129	
130	        let client = match self.http_client {
131	            Some(hc) => async_openai::Client::with_config(config).with_http_client(hc),
132	            None => async_openai::Client::with_config(config),
133	        };
134	
135	        Ok(OpenAiModel::new(self.model_id, self.backend, client, caps))
136	    }
137	}
