30	/// Entry point for Chat Completions backend. Always streams.
31	///
32	/// Builds a streaming Chat Completions request via async-openai (with
33	/// `stream_options.include_usage = true` so the final chunk carries
34	/// the full token-usage snapshot), then translates the SSE stream through
35	/// [`ChatTranslator`] into a `BoxStream<Result<ModelEvent, ModelError>>`.
36	///
37	/// Cancellation via [`CancellationToken`] is honoured at both the initial
38	/// request future and each poll of the upstream SSE stream (`tokio::select!`
39	/// biased toward the cancel arm).
40	pub(crate) async fn invoke(
41	    model: &OpenAiModel,
42	    request: ModelRequest,
43	    cancel: CancellationToken,
44	) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
45	    let body = build_request(model, &request, /* streaming */ true)?;
46	    let client = model.client.clone();
47	
48	    let s = stream! {
49	        // `client.chat()` returns a `Chat<'_, C>` that borrows `client`.
50	        // We must bind it to a local so the borrow lives long enough for
51	        // `create_stream(body)` to be awaited.
52	        let chat_client = client.chat();
53	        let create_fut = chat_client.create_stream(body);
54	
55	        let response = tokio::select! {
56	            biased;
57	            _ = cancel.cancelled() => return,
58	            r = create_fut => r,
59	        };
60	
61	        let mut upstream = match response {
62	            Ok(s) => s,
63	            Err(e) => {
64	                yield Err(map_openai_error(e));
